// Clean up initial summary for downstream use
// This content feeds directly into prompt_perso_prof AND gets inserted to SB later
const summaryRaw = $('Initial_summary1').first().json.text || '';
const reportId = $('Process Survey Data1').first().json.report_id;

// Clean markdown formatting, convert to HTML (same logic as original)
let content = summaryRaw
  .replace(/###\s*\*\*([^*]+)\*\*/g, '<h5>$1</h5>')
  .replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>')
  .replace(/\*([^*]+)\*/g, '$1')
  .trim();

return [{
  json: {
    report_id: reportId,
    content: content
  }
}];

// Encore v2 survey parser (survey 00000000-0000-0000-0000-000000000004).
// Question ids and stored values: docs/encore-v2-question-ids.md in the cairnly repo.
// Rewritten 2026-11-10 for v2; the v1 parser (b2b2b2b2 ids) is in
// n8n_wfs_cairnly/backups/WF1P - Encore Profile Insert EN_BACKUP_pre_v2_20261110.json
// Output shape is unchanged: {report_id, user_id, preferred_language, summary, questions[]}.

// 1. MASTER SCHEMA - key = question number as shown in the survey (7.2 is reserved, not in the launch survey)
  const SURVEY_SCHEMA = {
    // --- SECTION 1: About you ---
    "1.1": { uuid: "c3c3c3c3-0001-4000-a000-000000000001", question: "What is your first name?", type: "short_text", options: [], description: "" },
    "1.2": { uuid: "c3c3c3c3-0001-4000-a000-000000000002", question: "How old are you?", type: "number", options: [], description: "" },
    "1.3": { uuid: "c3c3c3c3-0001-4000-a000-000000000003", question: "Where do you live?", type: "dropdown", options: ["Northern and Western Europe", "Southern and Eastern Europe", "United Kingdom (London)", "United Kingdom (Other)", "United States (High-Cost Regions)", "United States (Average-Cost Regions)", "United States (Lower-Cost Regions)", "Canada", "Australia and New Zealand", "Switzerland"], description: "So we can suggest options near you." },
    "1.4": { uuid: "c3c3c3c3-0001-4000-a000-000000000004", question: "Where are you in your working life?", type: "multiple_choice", options: ["Still working, I stop in more than a year", "Still working, I stop within a year", "Working less, step by step", "Stopped less than a year ago", "Stopped one to three years ago", "Stopped more than three years ago", "I run my own business and want to step back"], description: "" },
    "1.5": { uuid: "c3c3c3c3-0001-4000-a000-000000000005", question: "Whose decision is it to stop working?", type: "multiple_choice", options: ["My own", "Partly mine", "It was decided for me, for example in a reorganisation", "Nothing is decided yet"], description: "" },
    // --- SECTION 2: Your working life ---
    "2.1": { uuid: "c3c3c3c3-0002-4000-a000-000000000001", question: "Which roles shaped your working life?", type: "career_history", options: [], description: "Up to 4 roles. For each: the role, the organisation, start and end year, and a few words on what you did there (type or speak). Paid and unpaid work both count, including years spent caring for family. Speak other languages? Mention them in any box. If you uploaded your CV, we filled this in: check it and add what matters to you." },
    "2.2": { uuid: "c3c3c3c3-0002-4000-a000-000000000002", question: "What were you known for at work?", type: "multiple_choice", options: ["Explaining things clearly", "Organising and planning", "Listening and giving advice", "Solving practical problems", "Leading a team", "Bringing people together", "Numbers and money", "Writing", "Selling and convincing", "Making or building things", "Looking after people", "Spotting risks early", "Starting new things"], description: "What colleagues came to you for. Pick up to 5." },
    "2.3": { uuid: "c3c3c3c3-0002-4000-a000-000000000003", question: "What did you love about your work?", type: "long_text", options: [], description: "The parts you would gladly do again, even unpaid. For example: \"Sitting down with a new colleague and seeing it click.\"" },
    "2.4": { uuid: "c3c3c3c3-0002-4000-a000-000000000004", question: "What are you glad to leave behind?", type: "multiple_choice", options: ["Long meetings", "Office politics", "Targets and reviews", "Commuting", "Being on call", "Fixed hours", "A lot of travel", "Pressure and deadlines", "Managing people", "Not much, I liked it all"], description: "Pick up to 3." },
    // --- SECTION 3: Being useful ---
    "3.1": { uuid: "c3c3c3c3-0003-4000-a000-000000000001", question: "Which of these feels most true for you right now?", type: "multiple_choice", options: ["I want to stay useful, but not in a job like my old one. I don't know what fits me.", "Work gave my week its shape. I'm not sure what will replace it.", "Most of my contacts came through work. I don't want to lose that.", "My partner and I need to figure this out together.", "None of these. I mostly want to make the most of the coming years."], description: "Pick the one that comes closest." },
    "3.2": { uuid: "c3c3c3c3-0003-4000-a000-000000000002", question: "When did you feel most useful?", type: "long_text", options: [], description: "At work or outside it, recently or long ago. What were you doing, and for whom? For example: \"Coaching the youth team at our hockey club.\"" },
    "3.3": { uuid: "c3c3c3c3-0003-4000-a000-000000000003", question: "Who would you most like to be useful to?", type: "multiple_choice", options: ["One person at a time, like a student or a starter", "A team or organisation", "Young people", "People going through a hard time", "My own field or profession", "My town or neighbourhood", "A cause, like nature, culture or health", "My family", "Myself, by making or learning something"], description: "Pick up to 3." },
    "3.4": { uuid: "c3c3c3c3-0003-4000-a000-000000000004", question: "Which of these would you like to explore?", type: "multiple_choice", options: ["Paid work, part time or per project", "Interim or freelance work in my field", "A board, supervisory or advisory role", "Mentoring or coaching", "Teaching or training", "Volunteering", "Starting something small of my own", "Learning something new", "I don't know yet, show me what fits"], description: "Pick all that appeal. Board and supervisory roles come with legal duties; your report explains what that means." },
    "3.5": { uuid: "c3c3c3c3-0003-4000-a000-000000000005", question: "Is there something you already tried, or an idea you keep coming back to?", type: "long_text", options: [], description: "Tell us how it went. Skip this if nothing comes to mind." },
    // --- SECTION 4: What suits you ---
    "4.1": { uuid: "c3c3c3c3-0004-4000-a000-000000000001", question: "After a day with lots of people, how do you feel?", type: "multiple_choice", options: ["Full of energy", "Good, but I need some quiet after", "A bit tired", "Drained, I need time alone"], description: "" },
    "4.2": { uuid: "c3c3c3c3-0004-4000-a000-000000000002", question: "What should your week look like?", type: "multiple_choice", options: ["Fixed days and set appointments", "A steady rhythm with room to move", "Free, I commit per project or season", "Completely open"], description: "" },
    "4.3": { uuid: "c3c3c3c3-0004-4000-a000-000000000003", question: "Which role suits you best?", type: "multiple_choice", options: ["Leading, taking charge", "Doing, rolling up my sleeves", "Advising, being the sounding board", "Teaching, helping someone grow", "Connecting, bringing people together", "It depends on the setting"], description: "" },
    "4.4": { uuid: "c3c3c3c3-0004-4000-a000-000000000004", question: "What matters most to you in the coming years?", type: "multiple_choice", options: ["Being useful to others", "Keeping my mind busy", "Having people around me", "A rhythm to my week", "My experience being valued", "Some extra income", "Freedom for travel and family", "Making or building something", "Giving back to a cause", "Learning something new"], description: "Pick 3." },
    // --- SECTION 5: The people around you ---
    "5.1": { uuid: "c3c3c3c3-0005-4000-a000-000000000001", question: "How do your plans relate to your partner's?", type: "multiple_choice", options: ["We make plans together", "We each do our own thing, and that works", "We haven't really talked about it yet", "We want different things", "I don't have a partner"], description: "" },
    "5.2": { uuid: "c3c3c3c3-0005-4000-a000-000000000002", question: "What does your partner hope for in the coming years?", type: "long_text", options: [], description: "In their words, if you can. Skip this if it doesn't apply." },
    "5.3": { uuid: "c3c3c3c3-0005-4000-a000-000000000003", question: "How do you feel about the people around you?", type: "multiple_choice", options: ["I have plenty of good people around me", "Enough, but new contacts would be welcome", "I miss the daily contact from work", "I'd like to meet people in the same phase of life"], description: "" },
    "5.4": { uuid: "c3c3c3c3-0005-4000-a000-000000000004", question: "Do you like to do things on your own or with others?", type: "multiple_choice", options: ["On my own", "With one or two others", "As part of a group", "It doesn't matter"], description: "" },
    // --- SECTION 6: Fitting it into your life ---
    "6.1": { uuid: "c3c3c3c3-0006-4000-a000-000000000001", question: "How much time would you like to spend on what comes next?", type: "multiple_choice", options: ["A few hours a month", "Half a day a week", "One or two days a week", "Three days or more", "It depends on the season"], description: "" },
    "6.2": { uuid: "c3c3c3c3-0006-4000-a000-000000000002", question: "What is already fixed in your calendar?", type: "multiple_choice", options: ["Days with grandchildren", "Caring for someone", "Long trips or winters abroad", "Clubs or volunteering I want to keep", "Nothing fixed"], description: "Pick all that apply." },
    "6.3": { uuid: "c3c3c3c3-0006-4000-a000-000000000003", question: "Where would you like this to happen?", type: "multiple_choice", options: ["From home, online", "Close to home", "Within an hour's travel", "Anywhere, for the right thing"], description: "" },
    "6.4": { uuid: "c3c3c3c3-0006-4000-a000-000000000004", question: "Does it need to pay?", type: "multiple_choice", options: ["No, money isn't the point", "A little would be nice", "Yes, extra income matters to me"], description: "" },
    // --- SECTION 7: To finish ---
    "7.1": { uuid: "c3c3c3c3-0007-4000-a000-000000000001", question: "What would make this worth it for you?", type: "multiple_choice", options: ["A clear picture of what suits me now", "Options I hadn't thought of", "A first step I can take next week", "Help to talk it over with my partner", "Someone checking in with me in the coming months", "An honest view on an idea I already have"], description: "Pick up to 2." },
    "7.3": { uuid: "c3c3c3c3-0007-4000-a000-000000000003", question: "Anything else you'd like us to know?", type: "long_text", options: [], description: "" }
  };

  // Keep only the fields the slim career form (2.1) actually collects.
  function slimRole(r) {
      if (!r || typeof r !== 'object') return r;
      const end = r.isCurrent ? 'now' : (r.endYear || '');
      return {
          title: r.title || '',
          organisation: r.companyName || '',
          years: [r.startYear || '', end].filter(Boolean).join(' - '),
          what_they_did: (r.description || '').trim()
      };
  }

  // --- DATA PROCESSING ---
  const inputItem = $input.first().json;
  const rawResponses = inputItem.survey_responses?.responses || inputItem.body?.survey_responses?.responses || {};

  const reportId = inputItem.report_id || inputItem.body?.report_id || null;
  const userId = inputItem.user_id || inputItem.body?.user_id || null;

  const formattedQuestions = [];
  let answeredCount = 0;

  for (const [id, config] of Object.entries(SURVEY_SCHEMA)) {
      const answer = rawResponses[config.uuid];

      const result = {
          questionId: id,
          question: config.question,
          type: config.type,
          description: config.description || "",
          chosen: [],
          notChosen: [],
          hasAnswer: false
      };

      const isEmpty = answer === undefined || answer === null || answer === "" ||
          (Array.isArray(answer) && answer.length === 0);

      if (!isEmpty) {
          result.hasAnswer = true;
          answeredCount++;

          if (config.type === "career_history") {
              const roles = Array.isArray(answer) ? answer : [answer];
              result.chosen = roles.map(slimRole).filter(r => r && (typeof r !== 'object' || r.title));
          } else {
              const answerArray = Array.isArray(answer) ? answer : [answer];
              const cleanAnswers = answerArray.map(a => typeof a === 'string' ? a.replace(/\*\*/g, '').trim() : a);
              result.chosen = cleanAnswers;

              if (config.options && config.options.length > 0) {
                  result.notChosen = config.options.filter(opt =>
                      !cleanAnswers.some(userAns => String(userAns).trim() === opt));
              }
          }
      } else {
          result.notChosen = config.options || [];
      }

      formattedQuestions.push(result);
  }

  // Country typed in when the person picked "Elsewhere" in the region picker (sidecar answer, not a question).
  const elsewhere = rawResponses['__elsewhere_location'];
  if (typeof elsewhere === 'string' && elsewhere.trim()) {
      formattedQuestions.push({
          questionId: "1.3b",
          question: "Country or city typed in (region picker 'Elsewhere')",
          type: "short_text",
          description: "",
          chosen: [elsewhere.trim()],
          notChosen: [],
          hasAnswer: true
      });
  }

  return [{
      report_id: reportId,
      user_id: userId,
      preferred_language: inputItem.preferred_language || inputItem.body?.preferred_language || 'en',
      summary: {
          totalQuestions: Object.keys(SURVEY_SCHEMA).length,
          answeredQuestions: answeredCount
      },
      questions: formattedQuestions
  }];

// ---------------- CONFIG ----------------
// Encore v2 headings (2026-11-10). Must match prompt_perso_prof1 exactly, EN and NL ("u").
const SUBHEADER_PATTERNS_ALL = {
  en: {
    approach: ["What People Count On You For", "Where Your Energy Comes From", "Key Insight"],
    strengths: ["Your Core Strengths", "What Carries Over, and What Does Not", "Key Insight"],
    development: ["Old Habits in a New Setting", "What This Means for Your Choices", "Key Insight"],
    values: ["Your Values Now", "Choosing With Your Values", "Key Insight"]
  },
  nl: {
    approach: ["Waar mensen op u rekenen", "Waar uw energie vandaan komt", "Belangrijkste inzicht"],
    strengths: ["Uw kernkwaliteiten", "Wat u meeneemt, en wat niet", "Belangrijkste inzicht"],
    development: ["Oude gewoonten in een nieuwe omgeving", "Wat dit betekent voor uw keuzes", "Belangrijkste inzicht"],
    values: ["Uw waarden nu", "Kiezen met uw waarden", "Belangrijkste inzicht"]
  }
};
const __lang = ($('Process Survey Data1').first().json.preferred_language === 'nl') ? 'nl' : 'en';
const SUBHEADER_PATTERNS = SUBHEADER_PATTERNS_ALL[__lang];

// ---------------- HELPERS ----------------
function cleanMarkdown(text) {
  return text
    .replace(/\*\*(.*?)\*\*/g, '$1')
    .replace(/__(.*?)__/g, '$1')
    .replace(/\*(.*?)\*/g, '$1')
    .trim();
}

function extractSections(content, sectionType) {
  const patterns = SUBHEADER_PATTERNS[sectionType] || [];
  if (patterns.length === 0) return [];

  const regex = new RegExp(`(${patterns.join('|')}):?`, 'gi');
  const parts = content.split(regex).filter(Boolean);
  const sections = [];

  for (let i = 0; i < parts.length; i++) {
    const p = parts[i].trim();
    if (patterns.some(ph => new RegExp(ph, 'i').test(p))) {
      const subheader = p.replace(/:$/, '').trim();
      const next = parts[i + 1] ? parts[i + 1].trim() : '';
      sections.push({ subheader, content: next });
      i++;
    }
  }
  // Fallback: if no known subheaders matched (e.g. localized text the
  // patterns don't cover), keep the whole section as one block instead of
  // dropping it. Guarantees no section is ever lost to a pattern miss.
  if (sections.length === 0) {
    const whole = content.trim();
    return whole ? [{ subheader: '', content: whole }] : [];
  }
  return sections;
}

// ---------------- SOURCE DATA ----------------
const narrativeData = $('generate_personality_narrative1').first().json;
const reportId = $('Process Survey Data1').first().json.report_id;

// Get the init_summary content from Prep node (already cleaned HTML)
const initSummaryContent = $('Prep init_summary').first().json.content;

// ============== Extract personality_scores tag ==============
// The prompt appends a hidden <personality_scores>{...}</personality_scores>
// tag at the very end of the narrative. Pull it out, parse the JSON, and
// strip the tag from the text BEFORE we parse sections so the prose stays
// clean. The scores get attached to the `approach` section row's metadata
// column, where the dashboard's Personality Radar reads them from.
let personalityScores = null;
let narrativeText = narrativeData.text || '';
const scoresMatch = narrativeText.match(/<personality_scores>\s*([\s\S]*?)\s*<\/personality_scores>/i);
if (scoresMatch) {
  try {
    personalityScores = JSON.parse(scoresMatch[1].trim());
  } catch (err) {
    console.warn('[extract_report_sections] personality_scores JSON parse failed:', err.message);
  }
  narrativeText = narrativeText.replace(scoresMatch[0], '').trim();
}
// ============================================================

// ---------------- NARRATIVE EXTRACTION ----------------
const titleRegex = /#{1,3}\s*([^\n#]+)/g;
const titles = [];
let match;
while ((match = titleRegex.exec(narrativeText)) !== null) {
  titles.push(match[1].trim());
}

const contents = narrativeText.split(/#{1,3}\s*[^\n#]+\n*/g);
contents.shift();

const sectionTypes = ['approach', 'strengths', 'development', 'values'];
const parsedSections = [];

for (let i = 0; i < contents.length; i++) {
  const sectionType = sectionTypes[i];
  const raw = cleanMarkdown(contents[i]);
  parsedSections.push(extractSections(raw, sectionType));
}

// ---------------- OUTPUT ALL 5 SECTIONS ----------------
// init_summary + 4 narrative sections, all inserted to SB in one batch.
// Approach gets the personality_scores attached as metadata.
// Other sections leave metadata null.
const allSections = [
  {
    section_type: 'init_summary',
    title: 'Initial Summary',
    content: initSummaryContent,
    isRawContent: true,
    metadata: null
  },
  {
    section_type: 'approach',
    title: titles[0] || null,
    content: parsedSections[0] || [],
    metadata: personalityScores ? { personality_scores: personalityScores } : null
  },
  { section_type: 'strengths',   title: titles[1] || null, content: parsedSections[1] || [], metadata: null },
  { section_type: 'development', title: titles[2] || null, content: parsedSections[2] || [], metadata: null },
  { section_type: 'values',      title: titles[3] || null, content: parsedSections[3] || [], metadata: null }
];

return allSections
  .filter(s => s.content && (s.isRawContent || (Array.isArray(s.content) && s.content.length > 0)))
  .map(s => {
    let formatted;

    if (s.isRawContent) {
      formatted = s.content;
    } else {
      formatted = s.content.map(block => {
        const subheader = block.subheader && block.subheader.trim()
          ? `<h5>${block.subheader}</h5>\n\n`
          : '';
        const text = block.content || '';
        return `${subheader}${text}`;
      }).join('\n\n');
    }

    // CRITICAL: every row MUST have the same set of keys. PostgREST
    // bulk insert (PGRST102) rejects arrays where keys differ across rows.
    // metadata is always present and is null unless this is the approach row.
    return {
      report_id: reportId,
      section_type: s.section_type,
      title: s.title,
      content: formatted,
      metadata: s.metadata ?? null,
      language: __lang
    };
  });
